package ganymedes01.etfuturum;

import ganymedes01.etfuturum.entities.*;
import net.minecraft.entity.*;
import net.minecraft.entity.passive.*;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.init.Items;
import net.minecraft.inventory.EntityEquipmentSlot;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.*;
import net.minecraft.util.math.*;
import net.minecraft.village.Village;
import net.minecraft.world.*;
import net.minecraftforge.event.entity.EntityStruckByLightningEvent;
import net.minecraftforge.event.entity.living.*;
import net.minecraftforge.event.entity.player.PlayerInteractEvent;
import net.minecraftforge.event.world.NoteBlockEvent;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.fml.common.eventhandler.*;
import net.minecraftforge.fml.common.gameevent.TickEvent;

@Mod.EventBusSubscriber(modid=UAB.ID)
public final class ModernMobEvents {
    private ModernMobEvents(){}
    @SubscribeEvent public static void world(TickEvent.WorldTickEvent event){if(event.phase==TickEvent.Phase.END&&!event.world.isRemote&&event.world.provider.getDimension()==0&&event.world.getTotalWorldTime()%20==0)RaidProgress.get(event.world).tick(event.world);}
    @SubscribeEvent public static void player(TickEvent.PlayerTickEvent event){EntityPlayer player=event.player;if(event.phase!=TickEvent.Phase.END||player.world.isRemote||player.ticksExisted%20!=0)return;NBTTagCompound data=player.getEntityData();for(String timer:new String[]{"EFRBadOmen","EFRHeroOfVillage","EFRTrialOmen"})if(data.getInteger(timer)>0)data.setInteger(timer,Math.max(0,data.getInteger(timer)-20));if(player.world.provider.getDimension()==0&&Features.enabled("entities.enableRaids")&&data.getInteger("EFRBadOmen")>0&&player.world.getDifficulty()!=EnumDifficulty.PEACEFUL&&!player.capabilities.disableDamage){Village village=player.world.getVillageCollection().getNearestVillage(player.getPosition(),0);if(village!=null&&RaidProgress.get(player.world).start(player.world,player,village))data.setInteger("EFRBadOmen",0);}if(player.ticksExisted%12000==0)playerSpawns(player);}
    @SubscribeEvent(priority=EventPriority.LOWEST) public static void death(LivingDeathEvent event){if(!event.getEntityLiving().world.isRemote&&event.getEntityLiving() instanceof EntityLiving)RaidProgress.get(event.getEntityLiving().world).died((EntityLiving)event.getEntityLiving());}
    @SubscribeEvent public static void membership(LivingEvent.LivingUpdateEvent event){if(event.getEntityLiving().world.isRemote||event.getEntityLiving().ticksExisted%20!=0||!(event.getEntityLiving() instanceof EntityCreature)||event.getEntityLiving() instanceof EntityIllager)return;EntityCreature entity=(EntityCreature)event.getEntityLiving();int raid=entity.getEntityData().getInteger("EFRRaid");if(raid!=0&&!RaidProgress.get(entity.world).isActive(raid)){entity.getEntityData().removeTag("EFRRaid");entity.detachHome();}}
    @SubscribeEvent public static void note(NoteBlockEvent.Play event){if(!event.getWorld().isRemote)for(EntityAllay allay:event.getWorld().getEntitiesWithinAABB(EntityAllay.class,new AxisAlignedBB(event.getPos()).grow(16)))allay.hearNote(event.getPos());}
    @SubscribeEvent public static void fall(LivingFallEvent event){EntityLivingBase entity=event.getEntityLiving();NBTTagCompound data=entity.getEntityData();if(data.getLong("EFRWindLaunchUntil")>entity.world.getTotalWorldTime()){event.setDistance(Math.max(0,(float)(data.getDouble("EFRWindLaunchY")-entity.posY)));data.removeTag("EFRWindLaunchUntil");data.removeTag("EFRWindLaunchY");}}
    @SubscribeEvent(priority=EventPriority.HIGH) public static void armor(LivingHurtEvent event){if(event.getEntityLiving().world.isRemote||!(event.getEntityLiving() instanceof EntityWolf)||event.getSource().isUnblockable())return;EntityWolf wolf=(EntityWolf)event.getEntityLiving();ItemStack armor=wolf.getItemStackFromSlot(EntityEquipmentSlot.CHEST);if(wolf.isTamed()&&armor.getItem()==Content.item("wolf_armor")){armor.damageItem(MathHelper.ceil(event.getAmount()),wolf);event.setAmount(0);if(armor.isEmpty())wolf.setItemStackToSlot(EntityEquipmentSlot.CHEST,ItemStack.EMPTY);}}
    @SubscribeEvent(priority=EventPriority.LOWEST) public static void equipment(PlayerInteractEvent.EntityInteract event){if(!(event.getTarget() instanceof EntityWolf)||event.getItemStack().isEmpty())return;EntityWolf wolf=(EntityWolf)event.getTarget();EntityPlayer player=event.getEntityPlayer();if(!wolf.isTamed()||!wolf.isOwner(player))return;ItemStack held=event.getItemStack(),armor=wolf.getItemStackFromSlot(EntityEquipmentSlot.CHEST);if(Content.available("wolf_armor")&&held.getItem()==Content.item("wolf_armor")&&armor.isEmpty()&&!wolf.isChild()){if(!wolf.world.isRemote){ItemStack copy=held.copy();copy.setCount(1);wolf.setItemStackToSlot(EntityEquipmentSlot.CHEST,copy);wolf.setDropChance(EntityEquipmentSlot.CHEST,2);if(!player.capabilities.isCreativeMode)held.shrink(1);}handled(event);}else if(!armor.isEmpty()&&armor.getItem()==Content.item("wolf_armor")&&held.getItem()==Items.SHEARS){if(!wolf.world.isRemote){boolean delivered=ItemDelivery.drop(wolf,armor,0);if(delivered){wolf.setItemStackToSlot(EntityEquipmentSlot.CHEST,ItemStack.EMPTY);held.damageItem(1,player);}}handled(event);}else if(armor.getItem()==Content.item("wolf_armor")&&Content.available("armadillo_scute")&&held.getItem()==Content.item("armadillo_scute")&&armor.isItemDamaged()){if(!wolf.world.isRemote){armor.setItemDamage(Math.max(0,armor.getItemDamage()-8));wolf.setItemStackToSlot(EntityEquipmentSlot.CHEST,armor.copy());if(!player.capabilities.isCreativeMode)held.shrink(1);}handled(event);}}
    private static void handled(PlayerInteractEvent event){event.setCancellationResult(EnumActionResult.SUCCESS);event.setCanceled(true);}
    @SubscribeEvent(priority=EventPriority.LOWEST) public static void lightning(EntityStruckByLightningEvent event){if(event.getEntity().world.isRemote||!(event.getEntity() instanceof EntityMooshroom)||!Features.enabled("entities.enableBrownMooshroom"))return;EntityMooshroom original=(EntityMooshroom)event.getEntity();String bolt=event.getLightning().getUniqueID().toString();if(bolt.equals(original.getEntityData().getString("EFRMooshroomBolt"))){event.setCanceled(true);return;}NBTTagCompound saved=new NBTTagCompound();original.writeToNBT(saved);EntityMooshroom changed=original instanceof EntityBrownMooshroom?new EntityMooshroom(original.world):new EntityBrownMooshroom(original.world);changed.readFromNBT(saved);changed.getEntityData().setString("EFRMooshroomBolt",bolt);original.setDead();if(original.world.spawnEntity(changed))event.setCanceled(true);else{original.isDead=false;if(((WorldServer)original.world).getEntityFromUuid(original.getUniqueID())==null)original.world.spawnEntity(original);}}
    @SubscribeEvent(priority=EventPriority.LOWEST) public static void construction(net.minecraftforge.event.world.BlockEvent.PlaceEvent event){if(event.getWorld().isRemote||event.getPlacedBlock().getBlock()!=net.minecraft.init.Blocks.PUMPKIN||!MobRegistry.enabled(EntityCopperGolem.class)||event.getWorld().getBlockState(event.getPos().down()).getBlock()!=Content.block("copper_block"))return;BlockPos pos=event.getPos();EntityCopperGolem golem=new EntityCopperGolem(event.getWorld());golem.setLocationAndAngles(pos.getX()+.5,pos.getY(),pos.getZ()+.5,0,0);if(event.getWorld().spawnEntity(golem)){event.getWorld().setBlockToAir(pos);if(Content.available("copper_chest"))event.getWorld().setBlockState(pos.down(),Content.block("copper_chest").getDefaultState(),3);}}
    private static void vibration(Entity source,double x,double y,double z){for(EntityWarden warden:source.world.getEntitiesWithinAABB(EntityWarden.class,source.getEntityBoundingBox().grow(16)))warden.vibration(source,x,y,z);}
    @SubscribeEvent public static void movement(LivingEvent.LivingUpdateEvent event){EntityLivingBase entity=event.getEntityLiving();if(!entity.world.isRemote&&entity.ticksExisted%10==0&&entity.onGround&&entity.getDistanceSq(entity.prevPosX,entity.prevPosY,entity.prevPosZ)>.0025)vibration(entity,entity.posX,entity.posY,entity.posZ);}
    @SubscribeEvent(priority=EventPriority.LOWEST) public static void vibrationHurt(LivingHurtEvent event){EntityLivingBase entity=event.getEntityLiving();if(!entity.world.isRemote)vibration(entity,entity.posX,entity.posY,entity.posZ);}
    @SubscribeEvent(priority=EventPriority.LOWEST) public static void vibrationBreak(net.minecraftforge.event.world.BlockEvent.BreakEvent event){if(!event.getWorld().isRemote)vibration(event.getPlayer(),event.getPos().getX(),event.getPos().getY(),event.getPos().getZ());}
    private static void playerSpawns(EntityPlayer player){World world=player.world;if(world.provider.getDimension()!=0||world.getDifficulty()==EnumDifficulty.PEACEFUL||!world.getGameRules().getBoolean("doMobSpawning")||player.capabilities.disableDamage)return;int x=MathHelper.floor(player.posX),z=MathHelper.floor(player.posZ);
        if(MobRegistry.enabled(EntityWanderingTrader.class)&&world.getTotalWorldTime()>24000&&world.rand.nextInt(10)==0&&world.getEntitiesWithinAABB(EntityWanderingTrader.class,player.getEntityBoundingBox().grow(96,48,96)).isEmpty()){int px=x+24+world.rand.nextInt(17),pz=z+world.rand.nextInt(49)-24;BlockPos column=new BlockPos(px,64,pz);if(world.isBlockLoaded(column)){BlockPos ground=world.getTopSolidOrLiquidBlock(column);EntityWanderingTrader trader=new EntityWanderingTrader(world);trader.setLocationAndAngles(px+.5,ground.getY(),pz+.5,0,0);if(!world.containsAnyLiquid(trader.getEntityBoundingBox())&&world.getCollisionBoxes(trader,trader.getEntityBoundingBox()).isEmpty()&&world.spawnEntity(trader)&&MobRegistry.enabled(EntityTraderLlama.class))for(int i=0;i<2;i++){EntityTraderLlama llama=new EntityTraderLlama(world);llama.setLocationAndAngles(px+i+.5,ground.getY(),pz+2.5,0,0);llama.onInitialSpawn(world.getDifficultyForLocation(ground),null);if(world.getCollisionBoxes(llama,llama.getEntityBoundingBox()).isEmpty()&&world.spawnEntity(llama))llama.setLeashHolder(trader,true);}}}
        if(!Features.enabled("entities.enablePatrols")||!MobRegistry.enabled(EntityPillager.class)||world.getTotalWorldTime()<120000||!world.isDaytime()||world.rand.nextInt(5)!=0||!world.getEntitiesWithinAABB(EntityPillager.class,player.getEntityBoundingBox().grow(96,48,96)).isEmpty())return;int px=x+(world.rand.nextBoolean()?1:-1)*(32+world.rand.nextInt(16)),pz=z+world.rand.nextInt(65)-32;BlockPos column=new BlockPos(px,64,pz);if(!world.isBlockLoaded(column))return;BlockPos ground=world.getTopSolidOrLiquidBlock(column);if(world.getVillageCollection().getNearestVillage(ground,32)!=null)return;for(int i=0;i<3+world.getDifficulty().getId();i++){BlockPos at=ground.add(i%3,0,i/3);if(!world.isBlockLoaded(at))continue;EntityPillager mob=new EntityPillager(world);mob.setLocationAndAngles(at.getX()+.5,at.getY(),at.getZ()+.5,0,0);if(world.containsAnyLiquid(mob.getEntityBoundingBox())||!world.getCollisionBoxes(mob,mob.getEntityBoundingBox()).isEmpty()||!world.checkNoEntityCollision(mob.getEntityBoundingBox()))continue;mob.setCaptain(i==0);mob.setHomePosAndDistance(player.getPosition(),48);world.spawnEntity(mob);}}
}
